def _close_keeping_error(resource):
    """Close after an active error; a cleanup failure must not replace that error."""
    try:
        resource.close()
    except Exception:
        pass


def stream_rows(resource, transform):
    # Generator body runs only on first next(), so construction and an
    # unstarted close() perform no read and no close.
    try:
        while True:
            row = resource.read_next()
            if row is None:
                break
            yield transform(row)
    except GeneratorExit:
        # Explicit generator.close(): cleanup errors propagate.
        resource.close()
        raise
    except BaseException:
        # Iteration or transform error: keep the original error.
        _close_keeping_error(resource)
        raise
    # Exhaustion: close exactly once; cleanup errors propagate.
    resource.close()
